WITH store_month_profit AS ( SELECT s.s_store_id, s.s_store_name, d.d_year, d.d_month_seq, cp.cp_department, SUM(ss.ss_net_profit) AS total_net_profit FROM store_sales ss JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk JOIN store s ON ss.ss_store_sk = s.s_store_sk JOIN catalog_page cp ON d.d_date_sk BETWEEN cp.cp_start_date_sk AND cp.cp_end_date_sk WHERE s.s_closed_date_sk IS NULL OR s.s_closed_date_sk > d.d_date_sk GROUP BY s.s_store_id, s.s_store_name, d.d_year, d.d_month_seq, cp.cp_department ) SELECT s_store_id, s_store_name, d_year, d_month_seq, cp_department, total_net_profit, AVG(total_net_profit) OVER (PARTITION BY d_year, d_month_seq) AS avg_monthly_profit, CASE WHEN total_net_profit > 1.2 * AVG(total_net_profit) OVER (PARTITION BY d_year, d_month_seq) THEN 'High' WHEN total_net_profit < 0.8 * AVG(total_net_profit) OVER (PARTITION BY d_year, d_month_seq) THEN 'Low' ELSE 'Medium' END AS profit_category, RANK() OVER (PARTITION BY d_year, d_month_seq ORDER BY total_net_profit DESC) AS profit_rank FROM store_month_profit ORDER BY d_year, d_month_seq, profit_rank LIMIT 100
